#!/usr/bin/env python3
"""Пересобрать src/sfx-data.js из assets/sfx (CC0-звуки, см. CREDITS.md)."""
import base64
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MIME = {'.ogg': 'audio/ogg', '.mp3': 'audio/mpeg', '.wav': 'audio/wav'}


def main():
    lines = [
        '// CC0 sound effects embedded as data URIs so the game also runs from file://.',
        '// See CREDITS.md for authors and licences. Generated by tools/embed_sfx.py',
        'window.SFX_DATA = {',
    ]
    for path in sorted((ROOT / 'assets' / 'sfx').iterdir()):
        if path.suffix not in MIME:
            continue
        payload = base64.b64encode(path.read_bytes()).decode('ascii')
        lines.append(f"  {path.stem!r}: 'data:{MIME[path.suffix]};base64,{payload}',")
    lines.append('};')
    out = ROOT / 'src' / 'sfx-data.js'
    out.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print(f'Wrote {out} ({out.stat().st_size} bytes)')


if __name__ == '__main__':
    main()
